import { useState, useEffect, useRef } from 'react';
import { HealthMetrics } from '../types';

export function useHealthData() {
  const [history, setHistory] = useState<HealthMetrics[]>([]);
  const [currentMetrics, setCurrentMetrics] = useState<HealthMetrics>({
    heartRate: 72,
    spO2: 98.2,
    temperature: 98.6,
    glucose: 110,
    timestamp: new Date().toISOString()
  });

  const historyRef = useRef<HealthMetrics[]>([]);

  useEffect(() => {
    // Pre-populate with 48 hours of simulated data (one reading per hour for baseline)
    const initial = Array.from({ length: 48 }).map((_, i) => {
      const baseGlucose = 100 + Math.sin(i / 4) * 20; // Circadian rhythm simulation
      return {
        heartRate: 65 + Math.random() * 15,
        spO2: 97 + Math.random() * 2.5,
        temperature: 97.8 + Math.random() * 1.2,
        glucose: baseGlucose + Math.random() * 15,
        timestamp: new Date(Date.now() - (48 - i) * 3600000).toISOString()
      };
    });
    setHistory(initial);
    historyRef.current = initial;

    const interval = setInterval(() => {
      // Simulate slow drift and noise
      const time = Date.now() / 10000;
      const newMetric: HealthMetrics = {
        heartRate: 72 + Math.sin(time) * 5 + (Math.random() - 0.5) * 4,
        spO2: Math.min(100, 98 + Math.cos(time / 2) * 1 + (Math.random() - 0.5) * 0.5),
        temperature: 98.4 + Math.sin(time / 3) * 0.3 + (Math.random() - 0.5) * 0.2,
        glucose: 110 + Math.sin(time / 5) * 25 + (Math.random() - 0.5) * 8,
        timestamp: new Date().toISOString()
      };

      setCurrentMetrics(newMetric);
      const updatedHistory = [...historyRef.current.slice(-100), newMetric];
      historyRef.current = updatedHistory;
      setHistory(updatedHistory);
    }, 4000);

    return () => clearInterval(interval);
  }, []);

  return { currentMetrics, history };
}

import React from 'react';
import { AreaChart, Area, ResponsiveContainer, YAxis } from 'recharts';

interface MetricCardProps {
  label: string;
  value: string | number;
  unit: string;
  icon: React.ReactNode;
  color: string; // Tailwind class like "emerald"
  hexColor: string; // Hex for chart
  data: any[];
  dataKey: string;
}

const MetricCard: React.FC<MetricCardProps> = ({ label, value, unit, icon, color, hexColor, data, dataKey }) => {
  // Extract last 12 points for the sparkline
  const sparkData = data.slice(-12);

  return (
    <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 flex flex-col gap-4 hover:shadow-xl hover:shadow-slate-200/50 transition-all duration-500 group">
      <div className="flex justify-between items-start">
        <div className={`p-3 rounded-2xl bg-${color}-50 text-${color}-600 group-hover:scale-110 transition-transform`}>
          {icon}
        </div>
        <div className="text-right">
          <span className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest">{label}</span>
          <div className="flex items-baseline justify-end gap-1 mt-1">
            <span className="text-2xl font-black text-slate-800">{value}</span>
            <span className="text-[10px] font-bold text-slate-500">{unit}</span>
          </div>
        </div>
      </div>

      <div className="h-14 w-full -mx-2">
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={sparkData}>
            <defs>
              <linearGradient id={`gradient-${dataKey}`} x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor={hexColor} stopOpacity={0.3}/>
                <stop offset="95%" stopColor={hexColor} stopOpacity={0}/>
              </linearGradient>
            </defs>
            <YAxis hide domain={['dataMin - 5', 'dataMax + 5']} />
            <Area 
              type="monotone" 
              dataKey={dataKey} 
              stroke={hexColor} 
              strokeWidth={3} 
              fillOpacity={1} 
              fill={`url(#gradient-${dataKey})`}
              dot={false}
              isAnimationActive={true}
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default MetricCard;
